    const regressedOp = structuredClone(done);
    regressedOp.status = "RUNNING";
    assert.throws(() => store.save(regressedOp), /COMPLETE cannot become RUNNING/);
    assert.equal(store.load("op-term").status, "COMPLETE");
  });

