import { test } from "node:test";
import assert from "node:assert";
import { ExecutionSpine, InvocationContext } from "../src/core/spine.js";
import { createDefaultRegistry } from "../src/core/capabilities.js";
import { extensionCapability } from "../src/core/extension_capabilities.js";

const dry: InvocationContext = { workspaceRoot: "/workspace", dryRun: true, readOnly: false };

function spineWith(handlerCalls: string[]) {
  const registry = createDefaultRegistry();
  registry.register(extensionCapability(
    { type: "function", function: { name: "mcp__s__push", description: "d", parameters: { type: "object", properties: {}, required: [] } } },
    { kind: "mcp", serverName: "s", url: "https://x.example" },
  ));
  const spine = new ExecutionSpine({ registry });
  for (const name of ["mcp__s__push", "manage_knowledge", "fetch_web"]) {
    spine.registerHandler(name, async () => { handlerCalls.push(name); return { success: true, output: "real" }; });
  }
  return spine;
}

const call = (spine: ExecutionSpine, toolName: string) =>
  spine.execute({ taskId: "t", actor: "agent", executionDomain: "agent_orchestration", toolName, args: {} }, dry);

test("a mutating extension tool and the knowledge store are simulated, not run, under dry-run", async () => {
  const ran: string[] = [];
  const spine = spineWith(ran);
  for (const name of ["mcp__s__push", "manage_knowledge"]) {
    const receipt = await call(spine, name);
    assert.equal(receipt.success, true);
    assert.equal(receipt.simulated, true);
    assert.match(receipt.output, /DRY-RUN SIMULATION/);
  }
  assert.deepEqual(ran, [], "no real handler ran");
});

test("a read capability still runs under dry-run", async () => {
  const ran: string[] = [];
  const receipt = await call(spineWith(ran), "fetch_web");
  assert.deepEqual(ran, ["fetch_web"]);
  assert.equal(receipt.output, "real");
});
