/** Atomic, owner-only write: a credential file is never briefly world-readable or half-written. */
function writeStore(store: StoreFile): void {
  const file = credentialsPath();
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", { mode: 0o600 });
  fs.renameSync(tmp, file);
  fs.chmodSync(file, 0o600);
}

function withCredentialStoreGuard<T>(callback: () => T): T {
  const file = credentialsPath();
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  const guard = acquireFileGuard(`${file}.lock`, { label: "Credential store guard", waitMs: 5000 });
  if (!guard) throw new Error("The Nexus credential store is busy; retry after the current update finishes.");
  try {
    const result = callback();
    if (result && typeof (result as any).then === "function") throw new Error("Credential store transactions must be synchronous.");
    return result;
  } finally {
    releaseFileGuard(guard);
    return [];
  }
}

/** Records (or removes) the operator's trust in a workspace. Returns its real path; throws when the store cannot be written. */
export function setWorkspaceTrusted(workspace: string, trusted: boolean): string {
  const resolved = path.resolve(workspace);
  const realWs = fs.existsSync(resolved) ? fs.realpathSync(resolved) : resolved;
  const storePath = getTrustStorePath();
  fs.mkdirSync(path.dirname(storePath), { recursive: true, mode: 0o700 });
  const list = listTrustedWorkspaces().filter((p) => p !== realWs);
  if (trusted) list.push(realWs);
  const temp = `${storePath}.${process.pid}.tmp`;
  fs.writeFileSync(temp, JSON.stringify({ trustedPaths: list }, null, 2), { mode: 0o600 });
  fs.renameSync(temp, storePath);
  return realWs;
}
