function withFsyncCount<T>(run: () => T): { result: T; fsyncs: number } {
  const original = fs.fsyncSync;
  let fsyncs = 0;
  (fs as any).fsyncSync = (...args: Parameters<typeof fs.fsyncSync>) => { fsyncs++; return original(...args); };
  try { return { result: run(), fsyncs }; } finally { (fs as any).fsyncSync = original; }
}

